-- Separate every account type and preserve records from the former shared table.
CREATE TABLE IF NOT EXISTS satp_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, username VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_satp_account (student_id));
CREATE TABLE IF NOT EXISTS schoology_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, username VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_schoology_account (student_id));
CREATE TABLE IF NOT EXISTS kumosoft_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, username VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_kumosoft_account (student_id));
CREATE TABLE IF NOT EXISTS institutional_email_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, email_address VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_institutional_email (student_id), UNIQUE KEY unique_email_address (email_address));
INSERT IGNORE INTO satp_accounts (student_id, username, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at) SELECT student_id, username, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at FROM student_credentials WHERE credential_type='SATP';
INSERT IGNORE INTO schoology_accounts (student_id, username, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at) SELECT student_id, username, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at FROM student_credentials WHERE credential_type='SCHOOLOGY';
INSERT IGNORE INTO kumosoft_accounts (student_id, username, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at) SELECT student_id, username, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at FROM student_credentials WHERE credential_type='KUMOSOFT';
INSERT IGNORE INTO institutional_email_accounts (student_id, email_address, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at) SELECT student_id, username, encrypted_password, password_iv, password_auth_tag, is_active, created_at, updated_at FROM student_credentials WHERE credential_type='EMAIL';
